pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    debug_assert_eq!(vals_2.len(), n);
    debug_assert_eq!(conds_1.len(), n);
    debug_assert_eq!(conds_2.len(), n);

    // Ensure output length matches inputs; overwrite allowed.
    if avgs.len() != n {
        avgs.resize(n, 0u64);
    }

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        debug_assert!(c1 || c2, "At least one condition must be true at each index");

        avgs[i] = match (c1, c2) {
            (true, true) => {
                // Overflow-safe average of two u64 values:
                // floor((a + b) / 2) without ever computing (a + b).
                let a = vals_1[i];
                let b = vals_2[i];
                (a / 2) + (b / 2) + ((a % 2 + b % 2) / 2)
            }
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => {
                // Should be impossible per problem statement; keep behavior defined.
                0u64
            }
        };
    }
}